//! Boolean polygon operations (intersect / union / difference / xor) for
//! simple, non-self-intersecting polygons with integer vertices.
//!
//! Algorithm: Greiner–Hormann. Both polygons are converted to circular
//! doubly-linked vertex lists, edge crossings are computed in `f64`, rounded
//! to the nearest `i64` (Clipper2 rounds to the grid) and inserted into both
//! lists; the crossings are then classified entry/exit and result polygons
//! are traced according to the requested operation.
//!
//! Limitations (by design): holes are ignored — every input path is treated
//! as one simple outer polygon — and vertex-touch / collinear-overlap
//! degeneracies are skipped rather than resolved with Clipper2 parity.
//! `FillRule` is accepted for API compatibility: for simple polygons all
//! fill rules agree, so it does not change the result.
//!
//! Output convention: result polygons are counter-clockwise (positive area).

use crate::geom::{area, FillRule, Path64, Paths64, Point64};

/// One vertex in a circular doubly-linked polygon list.
#[derive(Clone)]
struct Node {
    pt: Point64,
    next: usize,
    prev: usize,
    /// Matching crossing node in the other polygon's list.
    neighbor: Option<usize>,
    /// True for nodes inserted at edge crossings.
    intersect: bool,
    /// True if the polygon enters the other polygon's interior here.
    entry: bool,
}

/// A proper (edge-interior) crossing between a subject and a clip edge.
struct Cross {
    pt: Point64,
    s_edge: usize,
    t: f64,
    c_edge: usize,
    u: f64,
}

/// Compute the crossing of segments a1->a2 and b1->b2 in `f64`.
/// Returns the edge parameters (t, u) and the grid-rounded point, or `None`
/// for parallel/collinear segments and crossings at segment endpoints
/// (vertex-touch degeneracies are skipped defensively).
fn seg_intersect(a1: Point64, a2: Point64, b1: Point64, b2: Point64) -> Option<(f64, f64, Point64)> {
    let d = (a2.x - a1.x) as f64 * (b2.y - b1.y) as f64
        - (a2.y - a1.y) as f64 * (b2.x - b1.x) as f64;
    if d.abs() < 1e-12 {
        return None; // parallel or collinear
    }
    let t = ((b1.x - a1.x) as f64 * (b2.y - b1.y) as f64
        - (b1.y - a1.y) as f64 * (b2.x - b1.x) as f64)
        / d;
    let u = ((b1.x - a1.x) as f64 * (a2.y - a1.y) as f64
        - (b1.y - a1.y) as f64 * (a2.x - a1.x) as f64)
        / d;
    const EPS: f64 = 1e-9;
    if t <= EPS || t >= 1.0 - EPS || u <= EPS || u >= 1.0 - EPS {
        return None; // crossing at an endpoint: degenerate, skip
    }
    let x = a1.x as f64 + t * (a2.x - a1.x) as f64;
    let y = a1.y as f64 + t * (a2.y - a1.y) as f64;
    Some((t, u, Point64::new(x.round() as i64, y.round() as i64)))
}

/// Even-odd point-in-polygon test, exact via 128-bit integer arithmetic.
fn point_in_path(p: Point64, path: &Path64) -> bool {
    let mut inside = false;
    let n = path.len();
    for i in 0..n {
        let a = path[i];
        let b = path[(i + 1) % n];
        if (a.y > p.y) != (b.y > p.y) {
            // Is p.x left of the edge's x at height p.y? Compare without division.
            let lhs = (p.x as i128 - a.x as i128) * (b.y as i128 - a.y as i128);
            let rhs = (b.x as i128 - a.x as i128) * (p.y as i128 - a.y as i128);
            let crosses = if b.y > a.y { lhs < rhs } else { lhs > rhs };
            if crosses {
                inside = !inside;
            }
        }
    }
    inside
}

/// Both linked lists plus everything the tracer needs.
struct PairData {
    s: Vec<Node>,
    c: Vec<Node>,
}

/// Build the two circular lists with all crossings inserted and classified.
fn build_lists(subj: &Path64, clip: &Path64) -> PairData {
    let ns = subj.len();
    let nc = clip.len();

    // 1. Find all proper edge crossings.
    let mut crosses: Vec<Cross> = Vec::new();
    for i in 0..ns {
        let (a1, a2) = (subj[i], subj[(i + 1) % ns]);
        if a1 == a2 {
            continue; // zero-length edge guard
        }
        for j in 0..nc {
            let (b1, b2) = (clip[j], clip[(j + 1) % nc]);
            if b1 == b2 {
                continue;
            }
            if let Some((t, u, pt)) = seg_intersect(a1, a2, b1, b2) {
                crosses.push(Cross { pt, s_edge: i, t, c_edge: j, u });
            }
        }
    }

    // 2. Lay out each list in polygon order: vertex i, then its edge's
    //    crossings sorted by edge parameter. Node index == list order.
    let mut s: Vec<Node> = Vec::new();
    let mut c: Vec<Node> = Vec::new();
    let mut s_loc = vec![usize::MAX; crosses.len()];
    let mut c_loc = vec![usize::MAX; crosses.len()];

    let plain = |pt: Point64| Node { pt, next: 0, prev: 0, neighbor: None, intersect: false, entry: false };
    let xnode = |pt: Point64| Node { pt, next: 0, prev: 0, neighbor: None, intersect: true, entry: false };

    for i in 0..ns {
        s.push(plain(subj[i]));
        let mut ids: Vec<usize> = (0..crosses.len()).filter(|&k| crosses[k].s_edge == i).collect();
        ids.sort_by(|&a, &b| crosses[a].t.partial_cmp(&crosses[b].t).unwrap());
        for k in ids {
            s_loc[k] = s.len();
            s.push(xnode(crosses[k].pt));
        }
    }
    for j in 0..nc {
        c.push(plain(clip[j]));
        let mut ids: Vec<usize> = (0..crosses.len()).filter(|&k| crosses[k].c_edge == j).collect();
        ids.sort_by(|&a, &b| crosses[a].u.partial_cmp(&crosses[b].u).unwrap());
        for k in ids {
            c_loc[k] = c.len();
            c.push(xnode(crosses[k].pt));
        }
    }

    // 3. Circular next/prev links (list order == vec order by construction).
    let link = |nodes: &mut Vec<Node>| {
        let n = nodes.len();
        for i in 0..n {
            nodes[i].next = (i + 1) % n;
            nodes[i].prev = (i + n - 1) % n;
        }
    };
    link(&mut s);
    link(&mut c);

    // 4. Pair up matching crossings.
    for k in 0..crosses.len() {
        let (si, ci) = (s_loc[k], c_loc[k]);
        s[si].neighbor = Some(ci);
        c[ci].neighbor = Some(si);
    }

    // 5. Classify crossings entry/exit by alternating, seeded from whether
    //    each polygon's first vertex lies inside the other polygon.
    let mark = |nodes: &mut Vec<Node>, mut inside: bool| {
        for node in nodes.iter_mut() {
            if node.intersect {
                node.entry = !inside;
                inside = !inside;
            }
        }
    };
    let s0_inside = point_in_path(subj[0], clip);
    let c0_inside = point_in_path(clip[0], subj);
    mark(&mut s, s0_inside);
    mark(&mut c, c0_inside);

    PairData { s, c }
}

/// Append a vertex, dropping consecutive duplicates (from grid rounding).
fn push_pt(poly: &mut Path64, pt: Point64) {
    if poly.last() != Some(&pt) {
        poly.push(pt);
    }
}

/// Trace one result polygon starting at crossing `start` of the subject list.
/// Direction at each crossing: entry -> forward, exit -> backward (in the
/// list currently being walked). `s_entry`/`c_entry` are the *effective*
/// (possibly inverted) entry flags for the operation being computed.
fn trace(
    s: &[Node],
    c: &[Node],
    s_entry: &[bool],
    c_entry: &[bool],
    vis_s: &mut [bool],
    vis_c: &mut [bool],
    start: usize,
) -> Path64 {
    let mut poly: Path64 = Vec::new();
    let mut in_s = true;
    let mut cur = start;
    vis_s[start] = true;
    if let Some(n) = s[start].neighbor {
        vis_c[n] = true;
    }
    poly.push(s[start].pt);

    // Hard iteration cap so degenerate input can never hang us.
    let cap = 4 * (s.len() + c.len()) + 16;
    let mut steps = 0usize;

    loop {
        steps += 1;
        if steps > cap {
            break;
        }
        let (nodes, entry) = if in_s { (s, s_entry) } else { (c, c_entry) };
        let fwd = entry[cur];

        // Walk until the next crossing.
        loop {
            cur = if fwd { nodes[cur].next } else { nodes[cur].prev };
            steps += 1;
            if steps > cap {
                return poly;
            }
            if nodes[cur].intersect {
                break;
            }
            push_pt(&mut poly, nodes[cur].pt);
        }

        // Mark the crossing pair visited and hop to the other polygon.
        if in_s {
            vis_s[cur] = true;
            if let Some(n) = nodes[cur].neighbor {
                vis_c[n] = true;
            }
        } else {
            vis_c[cur] = true;
            if let Some(n) = nodes[cur].neighbor {
                vis_s[n] = true;
            }
        }
        match nodes[cur].neighbor {
            Some(nidx) => {
                in_s = !in_s;
                cur = nidx;
            }
            None => break,
        }
        if in_s && cur == start {
            break; // closed the loop back at the start crossing
        }
        push_pt(&mut poly, if in_s { s[cur].pt } else { c[cur].pt });
    }

    // Drop a duplicated closing vertex.
    if poly.len() > 1 && poly.first() == poly.last() {
        poly.pop();
    }
    poly
}

#[derive(Clone, Copy)]
enum Op {
    Intersection,
    Union,
    Difference, // subjects minus clips
}

/// Boolean operation between two simple polygons.
fn clip_pair(subj: &Path64, clip: &Path64, op: Op) -> Paths64 {
    let mut out: Paths64 = Vec::new();
    if subj.len() < 3 || clip.len() < 3 {
        return out; // degenerate input: nothing meaningful to compute
    }

    let pd = build_lists(subj, clip);
    let has_crossings = pd.s.iter().any(|n| n.intersect);

    if !has_crossings {
        // Disjoint or nested polygons: no tracing needed.
        let s_in_c = point_in_path(subj[0], clip);
        let c_in_s = point_in_path(clip[0], subj);
        match op {
            Op::Intersection => {
                if s_in_c {
                    out.push(subj.clone());
                } else if c_in_s {
                    out.push(clip.clone());
                }
            }
            Op::Union => {
                if s_in_c {
                    out.push(clip.clone());
                } else if c_in_s {
                    out.push(subj.clone());
                } else {
                    out.push(subj.clone());
                    out.push(clip.clone());
                }
            }
            Op::Difference => {
                // Nested clip would carve a hole; holes are ignored.
                if !s_in_c {
                    out.push(subj.clone());
                }
            }
        }
        return out;
    }

    // Greiner–Hormann tracing with operation-specific entry/exit inversion:
    // intersection keeps flags, union inverts both lists, difference inverts
    // the subject list. Tracing then starts at every effective "entry"
    // crossing of the subject list.
    let (inv_s, inv_c) = match op {
        Op::Intersection => (false, false),
        Op::Union => (true, true),
        Op::Difference => (true, false),
    };
    let s_entry: Vec<bool> = pd.s.iter().map(|n| n.entry ^ inv_s).collect();
    let c_entry: Vec<bool> = pd.c.iter().map(|n| n.entry ^ inv_c).collect();
    let mut vis_s = vec![false; pd.s.len()];
    let mut vis_c = vec![false; pd.c.len()];

    for i in 0..pd.s.len() {
        if !pd.s[i].intersect || vis_s[i] || !s_entry[i] {
            continue;
        }
        let poly = trace(&pd.s, &pd.c, &s_entry, &c_entry, &mut vis_s, &mut vis_c, i);
        if poly.len() >= 3 && area(&poly).abs() > 0.0 {
            out.push(poly);
        }
    }
    out
}

/// Enforce the output convention: counter-clockwise (positive area).
fn ensure_ccw(paths: &mut Paths64) {
    for p in paths.iter_mut() {
        if area(p) < 0.0 {
            p.reverse();
        }
    }
}

/// Intersection of all subject paths with all clip paths (pairwise).
pub fn intersect(subjects: &Paths64, clips: &Paths64, _fill_rule: FillRule) -> Paths64 {
    let mut out = Vec::new();
    for s in subjects {
        for c in clips {
            out.extend(clip_pair(s, c, Op::Intersection));
        }
    }
    ensure_ccw(&mut out);
    out
}

/// Union of subject and clip paths (pairwise per subject×clip pair).
pub fn union_op(subjects: &Paths64, clips: &Paths64, _fill_rule: FillRule) -> Paths64 {
    let mut out = Vec::new();
    if clips.is_empty() {
        out.extend(subjects.iter().cloned());
    } else if subjects.is_empty() {
        out.extend(clips.iter().cloned());
    } else {
        for s in subjects {
            for c in clips {
                out.extend(clip_pair(s, c, Op::Union));
            }
        }
    }
    ensure_ccw(&mut out);
    out
}

/// Subject paths minus the union of clip paths (clips applied sequentially).
pub fn difference(subjects: &Paths64, clips: &Paths64, _fill_rule: FillRule) -> Paths64 {
    let mut result = subjects.clone();
    for c in clips {
        let mut next = Vec::new();
        for s in &result {
            next.extend(clip_pair(s, c, Op::Difference));
        }
        result = next;
    }
    ensure_ccw(&mut result);
    result
}

/// Symmetric difference: (subjects − clips) ∪ (clips − subjects).
pub fn xor(subjects: &Paths64, clips: &Paths64, fill_rule: FillRule) -> Paths64 {
    let mut out = difference(subjects, clips, fill_rule);
    out.extend(difference(clips, subjects, fill_rule));
    ensure_ccw(&mut out);
    out
}

//! Test-harness stand-in for the shared geom.rs contract.

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct Point64 {
    pub x: i64,
    pub y: i64,
}

impl Point64 {
    pub fn new(x: i64, y: i64) -> Self {
        Self { x, y }
    }
}

pub type Path64 = Vec<Point64>;
pub type Paths64 = Vec<Path64>;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum FillRule {
    EvenOdd,
    NonZero,
    Positive,
    Negative,
}

/// Signed area; positive for counter-clockwise winding (y-up).
pub fn area(path: &Path64) -> f64 {
    let n = path.len();
    if n < 3 {
        return 0.0;
    }
    let mut a = 0.0f64;
    for i in 0..n {
        let p = path[i];
        let q = path[(i + 1) % n];
        a += p.x as f64 * q.y as f64 - q.x as f64 * p.y as f64;
    }
    a * 0.5
}

pub fn is_positive(path: &Path64) -> bool {
    area(path) > 0.0
}

pub fn cross(o: Point64, a: Point64, b: Point64) -> i128 {
    (a.x as i128 - o.x as i128) * (b.y as i128 - o.y as i128)
        - (a.y as i128 - o.y as i128) * (b.x as i128 - o.x as i128)
}

mod boolean;
mod geom;

use geom::{area, FillRule, Path64, Paths64, Point64};

fn pt(x: i64, y: i64) -> Point64 {
    Point64::new(x, y)
}

fn sorted_pts(p: &Path64) -> Vec<(i64, i64)> {
    let mut v: Vec<(i64, i64)> = p.iter().map(|q| (q.x, q.y)).collect();
    v.sort();
    v
}

fn main() {
    let subject: Paths64 = vec![vec![pt(0, 0), pt(100, 0), pt(100, 100), pt(0, 100)]];
    let clip: Paths64 = vec![vec![pt(50, 50), pt(150, 50), pt(150, 150), pt(50, 150)]];

    // --- intersect: exactly one quad (50,50),(100,50),(100,100),(50,100) ---
    let r = boolean::intersect(&subject, &clip, FillRule::EvenOdd);
    println!("intersect: {} path(s)", r.len());
    for p in &r {
        println!("  verts={:?} area={}", sorted_pts(p), area(p));
    }
    assert_eq!(r.len(), 1, "intersect must yield exactly 1 path");
    assert_eq!(
        sorted_pts(&r[0]),
        vec![(50, 50), (50, 100), (100, 50), (100, 100)]
    );
    assert!(area(&r[0]) > 0.0, "intersect output must be CCW");
    assert!((area(&r[0]) - 2500.0).abs() < 1e-9);

    // --- union: exactly one 8-vertex L-shape ---
    let r = boolean::union_op(&subject, &clip, FillRule::EvenOdd);
    println!("union: {} path(s)", r.len());
    for p in &r {
        println!("  verts={:?} area={}", sorted_pts(p), area(p));
    }
    assert_eq!(r.len(), 1, "union must yield exactly 1 path");
    assert_eq!(
        sorted_pts(&r[0]),
        vec![
            (0, 0),
            (0, 100),
            (50, 100),
            (50, 150),
            (100, 0),
            (100, 50),
            (150, 50),
            (150, 150)
        ]
    );
    assert!(area(&r[0]) > 0.0);
    assert!((area(&r[0]) - 17500.0).abs() < 1e-9);

    // --- difference: exactly one 6-vertex path ---
    let r = boolean::difference(&subject, &clip, FillRule::EvenOdd);
    println!("difference: {} path(s)", r.len());
    for p in &r {
        println!("  verts={:?} area={}", sorted_pts(p), area(p));
    }
    assert_eq!(r.len(), 1, "difference must yield exactly 1 path");
    assert_eq!(
        sorted_pts(&r[0]),
        vec![(0, 0), (0, 100), (50, 50), (50, 100), (100, 0), (100, 50)]
    );
    assert!(area(&r[0]) > 0.0);
    assert!((area(&r[0]) - 7500.0).abs() < 1e-9);

    // --- xor: exactly two paths, each area 7500 ---
    let r = boolean::xor(&subject, &clip, FillRule::EvenOdd);
    println!("xor: {} path(s)", r.len());
    for p in &r {
        println!("  verts={:?} area={}", sorted_pts(p), area(p));
    }
    assert_eq!(r.len(), 2, "xor must yield exactly 2 paths");
    let total: f64 = r.iter().map(|p| area(p).abs()).sum();
    assert!((total - 15000.0).abs() < 1e-9);
    for p in &r {
        assert!(area(p) > 0.0);
        assert!((area(p) - 7500.0).abs() < 1e-9);
    }

    // --- degenerate regressions: disjoint and nested inputs must not panic ---
    let far: Paths64 = vec![vec![pt(200, 200), pt(300, 200), pt(300, 300), pt(200, 300)]];
    let inner: Paths64 = vec![vec![pt(10, 10), pt(20, 10), pt(20, 20), pt(10, 20)]];
    assert_eq!(boolean::intersect(&subject, &far, FillRule::EvenOdd).len(), 0);
    assert_eq!(boolean::union_op(&subject, &far, FillRule::EvenOdd).len(), 2);
    assert_eq!(boolean::difference(&subject, &far, FillRule::EvenOdd).len(), 1);
    assert_eq!(boolean::xor(&subject, &far, FillRule::EvenOdd).len(), 2);
    assert_eq!(boolean::intersect(&inner, &subject, FillRule::EvenOdd).len(), 1);
    assert_eq!(boolean::union_op(&inner, &subject, FillRule::EvenOdd).len(), 1);
    assert_eq!(boolean::difference(&inner, &subject, FillRule::EvenOdd).len(), 0);
    assert_eq!(boolean::difference(&subject, &inner, FillRule::EvenOdd).len(), 1); // hole ignored
    assert_eq!(boolean::xor(&inner, &subject, FillRule::EvenOdd).len(), 1); // outer only

    println!("ALL TESTS PASSED");
}

